// conversionHook.js - Records paid events on checkout success
// Called by checkout completion endpoint after successful payment

const fs = require('fs');
const path = require('path');

const REVENUE_LOG = path.join(__dirname, '..', '..', 'data', 'revenue_events.log');

function recordPaidEvent(amount, currency = 'USD', metadata = {}) {
  const event = {
    type: 'paid',
    amount,
    currency,
    timestamp: new Date().toISOString(),
    metadata
  };
  fs.appendFileSync(REVENUE_LOG, JSON.stringify(event) + '\n');
  // Also update in-memory counter if applicable
  if (global.__revenueCounters) {
    global.__revenueCounters.paidEvents = (global.__revenueCounters.paidEvents || 0) + 1;
  }
  return true;
}

module.exports = { recordPaidEvent };
